class Node:
    __slots__=("type","line","col","op_col","op_line","args","kwargs")
    def __init__(self, typ, line=1, col=1, *args, **kwargs):
        self.type=typ; self.line=line; self.col=col; self.op_line=line; self.op_col=col; self.args=args; self.kwargs=kwargs
    def __repr__(self): return f"N({self.type},{self.kwargs})"
    def get(self, k, default=None): return self.kwargs.get(k, default)

def tok_display(tok):
    if tok.type=="eof": return ""
    if tok.type=="str": return tok.value
    if tok.type in ("template","template_head","template_middle","template_tail"): return "`"
    if tok.type=="regex": return "/" 
    if tok.type=="num": return js_num_to_string(tok.value)
    return str(tok.value)

class Parser:
    def __init__(self, tokens, filename=None, is_module=False, strict=False):
        self.toks=tokens; self.pos=0; self.filename=filename; self.is_module=is_module; self.global_strict=strict
        self.in_function=0; self.in_generator=False; self.in_async=False; self.in_loop=0; self.in_switch=0
        self.current_class_private=False
    def peek(self, off=0):
        j=min(self.pos+off, len(self.toks)-1); return self.toks[j]
    def next(self):
        t=self.toks[self.pos]
        if self.pos < len(self.toks)-1: self.pos+=1
        return t
    def at_eof(self): return self.peek().type=="eof"
    def is_punc(self, v, off=0): 
        t=self.peek(off); return t.type=="punc" and t.value==v
    def is_name(self, v=None, off=0):
        t=self.peek(off); 
        if t.type not in ("name","private"): return False
        return v is None or t.value==v
    def match_punc(self, v):
        if self.is_punc(v): self.next(); return True
        return False
    def match_name(self, v):
        if self.is_name(v): self.next(); return True
        return False
    def err(self, msg, tok=None):
        t=tok or self.peek(); raise ParserErrorEx(msg, t.line, t.col, self.filename)
    def expect_punc(self, v, msg=None):
        if self.is_punc(v): return self.next()
        self.err(msg or f"expecting '{v}'")
