        if node.type=="Identifier": return node
        if node.type=="ArrayLiteral":
            elems=[]
            for el in node.get("elems"):
                if el is None: elems.append(None)
                elif el.type=="Spread": elems.append(Node("Rest",el.line,el.col,pattern=self.literal_to_pattern(el.get("expr"))))
                elif el.type=="PatternDefault": elems.append(el) # not generated as literal
