// Mini data processing app
class EventEmitter {
  constructor(){ this.handlers={}; }
  on(ev, fn){ (this.handlers[ev] ||= []).push(fn); }
  emit(ev, data){ (this.handlers[ev]||[]).forEach(f=>f(data)); }
}
const emitter = new EventEmitter();
let logs=[];
emitter.on('data', d=>logs.push(`data:${d}`));
emitter.on('end', ()=>logs.push('done'));
const records = [
  {name:'alice', scores:[90,80,100], tags:['a','b']},
  {name:'bob', scores:[70,60], tags:['b','c']},
  {name:'carol', scores:[95,85,90,100], tags:['a']},
];
function process(records){
  return records.map(r=>{
    const avg=r.scores.reduce((a,b)=>a+b,0)/r.scores.length;
    return {...r, avg: Math.round(avg*10)/10, grade: avg>=90?'A':avg>=75?'B':'C'};
  }).sort((a,b)=>b.avg-a.avg);
}
const processed=process(records);
for(const r of processed){ emitter.emit('data', `${r.name}:${r.avg}:${r.grade}`); }
emitter.emit('end');
console.log(logs.join('\n'));
const tagCounts=new Map();
for(const r of records) for(const t of r.tags) tagCounts.set(t,(tagCounts.get(t)||0)+1);
console.log([...tagCounts.entries()].sort());
async function fetchAll(){
  const results=await Promise.all(processed.map(async r=>{
    const val=await Promise.resolve(r.avg*2);
    return `${r.name}=${val}`;
  }));
  console.log(results.join(', '));
}
fetchAll();
const [first, second]=processed;
console.log(first.name, second.name);
try { throw new RangeError("custom") } catch(e){ console.log(e.name) }
let total=processed.reduce((sum,r)=>sum+r.avg,0);
console.log(total.toFixed(1));
console.log(JSON.stringify(processed[0]));
let gen=function*(){ yield* processed.map(r=>r.name) };
console.log([...gen()].join('/'));
